#!/usr/bin/env bash
set -euo pipefail
GATE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)"
source "${GATE_DIR}/../lib/common.sh"
GATE_ID='agent-provider-contract'
GATE_NAME='Agent provider orchestration contract'
GATE_COMMAND='node scripts/lib/agent/providers/cursor-resume-setup.mjs self-test && python3 scripts/lib/agent/providers/cursor-resume-zip.py self-test && node scripts/lib/agent/providers/cursor-resume-selftest.mjs && node scripts/lib/agent/providers/claude-resume-setup.mjs self-test && node scripts/lib/agent/providers/claude-resume-selftest.mjs && node scripts/lib/agent/provider-smoke.mjs self-test && node scripts/lib/agent/development-selftest.mjs && node scripts/lib/agent/orchestration/outbox-selftest.mjs && node scripts/lib/agent/orchestration/slice-selftest.mjs && node scripts/lib/agent/harness/native-selftest.mjs && node scripts/lib/agent/orchestration/github-dispatch-selftest.mjs && node scripts/lib/agent/orchestration/continuation-dispatch-selftest.mjs && node scripts/lib/agent/orchestration/dispatch-intent-selftest.mjs && node scripts/lib/agent/orchestration/worker-preflight-selftest.mjs && node scripts/lib/agent/orchestration/controller-dispatch-selftest.mjs && node scripts/lib/agent/orchestration/worker-reconcile-selftest.mjs && node scripts/lib/agent/orchestration/worker-zip-selftest.mjs && node scripts/lib/agent/orchestration/development-ingest-selftest.mjs && node scripts/lib/agent/orchestration/failed-dispatch-selftest.mjs && node scripts/lib/agent/orchestration/controller-start-selftest.mjs && node scripts/lib/agent/orchestration/controller-request-selftest.mjs && node scripts/lib/agent/orchestration/result-artifact-selftest.mjs && node scripts/lib/agent/developer-canary.mjs self-test && node scripts/lib/agent/publisher/patch-preflight-selftest.mjs'
GATE_SUCCESS='provider invocation, identity, Harness, transition, checkpoint and canonical event fixtures pass'
GATE_FAILURE='a provider or agent development invariant or fixture failed'
GATE_REPAIR='fix canonical agent/provider contract implementation; do not suppress a fixture'
GATE_OWNER='scripts/lib/agent/provider-smoke.mjs'
gate_check() {
  gate_require_command node "Install Node.js to run provider contract fixtures." || return $?
  gate_require_command python3 "Install Python 3 to run ZIP safety contract fixtures." || return $?
  gate_run_invariant bash -c 'node scripts/lib/agent/providers/cursor-resume-setup.mjs self-test && python3 scripts/lib/agent/providers/cursor-resume-zip.py self-test && node scripts/lib/agent/providers/cursor-resume-selftest.mjs && node scripts/lib/agent/providers/claude-resume-setup.mjs self-test && node scripts/lib/agent/providers/claude-resume-selftest.mjs && node scripts/lib/agent/provider-smoke.mjs self-test && node scripts/lib/agent/development-selftest.mjs && node scripts/lib/agent/orchestration/outbox-selftest.mjs && node scripts/lib/agent/orchestration/slice-selftest.mjs && node scripts/lib/agent/harness/native-selftest.mjs && node scripts/lib/agent/orchestration/github-dispatch-selftest.mjs && node scripts/lib/agent/orchestration/continuation-dispatch-selftest.mjs && node scripts/lib/agent/orchestration/dispatch-intent-selftest.mjs && node scripts/lib/agent/orchestration/worker-preflight-selftest.mjs && node scripts/lib/agent/orchestration/controller-dispatch-selftest.mjs && node scripts/lib/agent/orchestration/worker-reconcile-selftest.mjs && node scripts/lib/agent/orchestration/worker-zip-selftest.mjs && node scripts/lib/agent/orchestration/development-ingest-selftest.mjs && node scripts/lib/agent/orchestration/failed-dispatch-selftest.mjs && node scripts/lib/agent/orchestration/controller-start-selftest.mjs && node scripts/lib/agent/orchestration/controller-request-selftest.mjs && node scripts/lib/agent/orchestration/result-artifact-selftest.mjs && node scripts/lib/agent/developer-canary.mjs self-test && node scripts/lib/agent/publisher/patch-preflight-selftest.mjs'
}
gate_main "$@"
